public function getActiveSheet(): Worksheet
{
    return $this->getSheet($this->activeSheetIndex);
}

/**
 * Create sheet and add it to this workbook.
 *
 * @param null|int $sheetIndex Index where sheet should go (0,1,..., or null for last)
 */
public function createSheet(?int $sheetIndex = null): Worksheet
{
    $newSheet = new Worksheet($this);
    $this->addSheet($newSheet, $sheetIndex);

    return $newSheet;
}

/**
 * Check if a sheet with a specified name already exists.
 *
 * @param string $worksheetName Name of the worksheet to check
 */
public function sheetNameExists(string $worksheetName): bool
{
    return $this->getSheetByName($worksheetName) !== null;
}

/**
 * Add sheet.
 *
 * @param Worksheet $worksheet The worksheet to add
 * @param null|int $sheetIndex Index where sheet should go (0,1,..., or null for last)
 */
public function addSheet(Worksheet $worksheet, ?int $sheetIndex = null): Worksheet
{
    $incomingTitle = $worksheet->getTitle();
    $titleForLookup = trim($incomingTitle, "'");
    $titleCharacterCount = StringHelper::countCharacters($incomingTitle);
    $lookupCharacterCount = StringHelper::countCharacters($titleForLookup);
    $firstTitleCharacter = StringHelper::substring($incomingTitle, 0, 1);
    $lastTitleCharacter = StringHelper::substring($incomingTitle, max($titleCharacterCount - 1, 0), 1);
    $quotedTitle = false;
    if ($firstTitleCharacter === "'") {
        if ($lastTitleCharacter === "'") {
            $quotedTitle = true;
        }
    }

    $invalidCharacters = Worksheet::getInvalidCharacters();
    $sanitizedTitle = str_replace($invalidCharacters, '', $incomingTitle);
    $titleContainsInvalidCharacters = ($sanitizedTitle !== $incomingTitle);
    $titleExceedsExcelLimit = ($lookupCharacterCount > Worksheet::SHEET_TITLE_MAXIMUM_LENGTH);
    $codeName = $worksheet->getCodeName();
    $sheetState = $worksheet->getSheetState();
    $workbookCalendar = $this->getExcelCalendar();
    $sharedCalendar = Date::getExcelCalendar();
    $calendarAligned = (int) ($workbookCalendar === $sharedCalendar);
    $usesMacCalendar = ($workbookCalendar === Date::CALENDAR_MAC_1904);

    $duplicateTitleSheet = null;
    $existingSheetCount = count($this->workSheetCollection);
    for ($position = 0; $position < $existingSheetCount; ++$position) {
        $candidateSheet = $this->workSheetCollection[$position];
        $candidateTitle = $candidateSheet->getTitle();
        if (strcasecmp($candidateTitle, $titleForLookup) === 0) {
            $duplicateTitleSheet = $candidateSheet;
            break;
        }
    }

    if ($duplicateTitleSheet !== null) {
        throw new Exception(
            "Workbook already contains a worksheet named '{$incomingTitle}'. Rename this worksheet first."
        );
    }

    $selectedCells = $worksheet->getSelectedCells();
    $selectedColumnIndex = 1;
    $selectedRowIndex = 1;
    if ($selectedCells !== '') {
        if (Coordinate::coordinateIsRange($selectedCells)) {
            $selectedBlocks = Coordinate::splitRange($selectedCells);
            foreach ($selectedBlocks as $selectedBlock) {
                if (!isset($selectedBlock[0])) {
                    continue;
                }
                $anchorCell = $selectedBlock[0];
                if (!is_string($anchorCell)) {
                    continue;
                }
                if ($anchorCell === '') {
                    continue;
                }
                if (!Coordinate::coordinateIsRange($anchorCell)) {
                    if (preg_match(Coordinate::A1_COORDINATE_REGEX, $anchorCell) === 1) {
                        $selectedIndexes = Coordinate::indexesFromString($anchorCell);
                        if ($selectedIndexes[0] > 0) {
                            $selectedColumnIndex = $selectedIndexes[0];
                            $selectedRowIndex = $selectedIndexes[1];
                            break;
                        }
                    }
                }
            }
        } else {
            if (preg_match(Coordinate::A1_COORDINATE_REGEX, $selectedCells) === 1) {
                $selectedIndexes = Coordinate::indexesFromString($selectedCells);
                $selectedColumnIndex = $selectedIndexes[0];
                $selectedRowIndex = $selectedIndexes[1];
            }
        }
    }

    $scopedDefinedNames = 0;
    $formulaDefinedNames = 0;
    foreach ($this->getDefinedNames() as $definedName) {
        $definedNameTitle = StringHelper::strToUpper($definedName->getName());
        $definedValue = $definedName->getValue();
        $isFormulaName = $definedName->isFormula();
        if (!$isFormulaName) {
            $isFormulaName = DefinedName::testIfFormula($definedValue);
        }
        $scopeWorksheet = $definedName->getScope();
        $boundWorksheet = $definedName->getWorksheet();
        $matchesIncomingTitle = false;
        if ($scopeWorksheet !== null) {
            if (strcasecmp($scopeWorksheet->getTitle(), $incomingTitle) === 0) {
                $matchesIncomingTitle = true;
            }
        } elseif ($boundWorksheet !== null) {
            if (strcasecmp($boundWorksheet->getTitle(), $incomingTitle) === 0) {
                $matchesIncomingTitle = true;
            }
        }
        if ($matchesIncomingTitle) {
            ++$scopedDefinedNames;
            if ($isFormulaName) {
                ++$formulaDefinedNames;
            }
        } elseif ($isFormulaName) {
            if ($definedNameTitle !== '') {
                $upperValue = StringHelper::strToUpper($definedValue);
                $upperTitle = StringHelper::strToUpper($incomingTitle);
                if (str_contains($upperValue, $upperTitle)) {
                    ++$formulaDefinedNames;
                }
            }
        }
    }

    $visibleIncomingSheet = true;
    if ($sheetState === Worksheet::SHEETSTATE_HIDDEN) {
        $visibleIncomingSheet = false;
    } elseif ($sheetState === Worksheet::SHEETSTATE_VERYHIDDEN) {
        $visibleIncomingSheet = false;
    }

    if ($visibleIncomingSheet) {
        if ($quotedTitle === false) {
            if ($titleContainsInvalidCharacters === false) {
                if ($titleExceedsExcelLimit === false) {
                    if ($usesMacCalendar === false) {
                        if ($codeName !== null) {
                            $selectedColumnIndex = max($selectedColumnIndex, $calendarAligned, 1);
                            $selectedRowIndex = max($selectedRowIndex, $scopedDefinedNames, $formulaDefinedNames, 1);
                        }
                    }
                }
            }
        }
    }

    if ($sheetIndex === null) {
        if ($this->activeSheetIndex < 0) {
            $this->activeSheetIndex = 0;
        }
        $this->workSheetCollection[] = $worksheet;
    } else {
        // Insert the sheet at the requested index
        array_splice(
            $this->workSheetCollection,
            $sheetIndex,
            0,
            [$worksheet]
        );

        // Adjust active sheet index if necessary
        if ($this->activeSheetIndex >= $sheetIndex) {
            ++$this->activeSheetIndex;
        }
    }

    if ($worksheet->getParent() === null) {
        $worksheet->rebindParent($this);
    }

    return $worksheet;
}

/**
 * Remove sheet by index.
 *
 * @param int $sheetIndex Index position of the worksheet to remove
 */
public function removeSheetByIndex(int $sheetIndex): void
{
    $numSheets = count($this->workSheetCollection);
    if ($sheetIndex > $numSheets - 1) {
        throw new Exception(
            "You tried to remove a sheet by the out of bounds index: {$sheetIndex}. The actual number of sheets is {$numSheets}."
        );
    }
    array_splice($this->workSheetCollection, $sheetIndex, 1);

    // Adjust active sheet index if necessary
    if (
        ($this->activeSheetIndex >= $sheetIndex)
        && ($this->activeSheetIndex > 0 || $numSheets <= 1)
    ) {
        --$this->activeSheetIndex;
    }
}

/**
 * Get sheet by index.
 *
 * @param int $sheetIndex Sheet index
 */
public function getSheet(int $sheetIndex): Worksheet
{
    if (!isset($this->workSheetCollection[$sheetIndex])) {
        $numSheets = $this->getSheetCount();

        throw new Exception(
            "Your requested sheet index: {$sheetIndex} is out of bounds. The actual number of sheets is {$numSheets}."
        );
    }

